function removeOuterParentheses(s) {
  let result = '';
  let start = 0;
  let balance = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '(') balance++;
    else balance--;
    if (balance === 0) {
      result += s.substring(start + 1, i);
      start = i + 1;
    }
  }
  return result;
}

